<div class="page-header mb-4"><div class="row"><div class="col"><div class="page-pretitle"><?=e($contract['contract_code'].' - '.$contract['title'])?></div><h2 class="page-title">جدول الكميات / نطاق الأعمال</h2></div><div class="col-auto"><a class="btn" href="/contracts/<?=(int)$contract['id']?>">العودة للعقد</a></div></div></div><div id="boq-root" data-contract="<?=(int)$contract['id']?>" data-token="<?=e($csrfToken)?>">
<?php if(!$boq):?><div class="empty card"><div class="empty-header">BOQ</div><p class="empty-title">لم يتم بدء نطاق العقد</p><?php if($canManage&&$contract['status']==='draft'):?><button class="btn btn-primary js-action" data-url="/contracts/<?=(int)$contract['id']?>/boq">بدء نطاق العقد</button><?php endif;?></div><?php else:?><div class="row g-3 mb-4"><div class="col"><div class="card card-sm"><div class="card-body"><span class="text-secondary">الحالة</span><div class="h3"><?=$boq['status']==='approved'?'معتمد':'مسودة'?></div></div></div></div><div class="col"><div class="card card-sm"><div class="card-body"><span class="text-secondary">الإجمالي العام</span><div class="h3"><?=e($total)?></div></div></div></div></div>
<?php $draft=$boq['status']==='draft'&&$contract['status']==='draft';if($draft&&$canManage):?><div class="mb-3"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#section-modal">إضافة قسم</button><?php if(!$sections):?><button class="btn btn-outline-danger js-action" data-url="/contracts/<?=(int)$contract['id']?>/boq/discard">حذف النطاق الاختياري</button><?php endif;?></div><?php endif;?>
