<?php if($boq&&$boq['status']==='draft'&&$canManage):?><div class="modal fade" id="section-modal"><div class="modal-dialog"><form class="modal-content boq-form" action="/contracts/<?=(int)$contract['id']?>/boq/sections"><div class="modal-header"><h5>إضافة قسم</h5></div><div class="modal-body"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><select class="form-select mb-2" name="work_section_id"><option value="">قسم مخصص</option><?php foreach($masters['sections'] as $m):?><option value="<?=$m['id']?>" data-code="<?=e($m['section_code'])?>" data-title="<?=e($m['name'])?>"><?=e($m['section_code'].' - '.$m['name'])?></option><?php endforeach;?></select><input class="form-control mb-2" name="section_code" required placeholder="كود القسم"><input class="form-control mb-2" name="title" required placeholder="عنوان القسم"><input class="form-control" type="number" min="1" name="sort_order" value="1" required></div><div class="modal-footer"><button class="btn btn-primary">حفظ</button></div></form></div></div><div class="modal fade" id="item-modal"><div class="modal-dialog"><form class="modal-content boq-form" action="/contracts/<?=(int)$contract['id']?>/boq/items"><div class="modal-header"><h5>إضافة بند</h5></div><div class="modal-body"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><input type="hidden" name="section_id"><select class="form-select mb-2" name="cost_code_id"><option value="">بند مخصص</option><?php foreach($masters['codes'] as $m):?><option value="<?=$m['id']?>" data-code="<?=e($m['cost_code'])?>" data-description="<?=e($m['name'])?>" data-unit="<?=$m['default_unit_id']?>"><?=e($m['cost_code'].' - '.$m['name'])?></option><?php endforeach;?></select><input class="form-control mb-2" name="item_code" placeholder="كود البند"><textarea class="form-control mb-2" name="description" required placeholder="الوصف التعاقدي"></textarea><select class="form-select mb-2" name="unit_id"><option value="">بدون وحدة</option><?php foreach($masters['units'] as $u):?><option value="<?=$u['id']?>"><?=e($u['name_ar'])?></option><?php endforeach;?></select><input class="form-control mb-2" type="number" step="0.0001" min="0" name="quantity" placeholder="الكمية"><input class="form-control mb-2" type="number" step="0.01" min="0" name="unit_rate" placeholder="سعر الوحدة"><input class="form-control" type="number" min="1" name="sort_order" value="1" required></div><div class="modal-footer"><button class="btn btn-primary">حفظ</button></div></form></div></div><?php endif;?><script src="/assets/js/modules/contract-boq.js" defer></script>
